SELECT * FROM (SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END opened_cohort, MIN(opened_date) min_opened_date, ROUND(STDDEV(sqft), 2) stddev_sqft FROM stores WHERE opened_date <= '2025-01-05' GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END) sub WHERE stddev_sqft < 25 ORDER BY 3, 1;
